import os
root='node_modules'
hits=0
for dirpath, dirs, files in os.walk('node_modules/@shikijs'):
    dirs[:] = [d for d in dirs if d not in ('node_modules',)]
    for f in files:
        if f.endswith(('.mjs','.js','.ts')) and 'map' not in f:
            p=os.path.join(dirpath,f)
            try:
                t=open(p,errors='ignore').read()
            except Exception:
                continue
            if 'shiki-dark' in t or 'htmlStyle' in t and 'defaultColor' in t:
                print(p, 'shiki-dark' in t, 'htmlStyle' in t)
                hits+=1

